// lib/programs.js — Another Degree Hotter data layer
// To add programs: append an entry to RAW_PROGRAMS with the next id.
// Slugs are computed automatically from school + field + first degree.

// ── Utilities ──────────────────────────────────────────────────────────────

export function slugify(str) {
  return str
    .toLowerCase()
    .replace(/[éèêë]/g, 'e')
    .replace(/[àáâãä]/g, 'a')
    .replace(/[ùúûü]/g, 'u')
    .replace(/[ìíîï]/g, 'i')
    .replace(/[ôõö]/g, 'o')
    .replace(/[–—]/g, '-')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

function buildSlug(p) {
  return `${slugify(p.school)}-${slugify(p.field)}-${slugify(p.degree[0])}`
}

export function gpaLabel(gpa) {
  if (gpa <= 3.0) return { text: `${gpa.toFixed(1)}`, level: 'accessible' }
  if (gpa <= 3.3) return { text: `${gpa.toFixed(1)}`, level: 'moderate' }
  return { text: `${gpa.toFixed(1)}`, level: 'selective' }
}

export function relatedDegreeLabel(val) {
  return { not_required: 'Not required', preferred: 'Preferred', required: 'Required' }[val] ?? val
}

