// ── Derived export ─────────────────────────────────────────────────────────

export const PROGRAMS = RAW_PROGRAMS.map(p => ({ ...p, slug: buildSlug(p) }))

export function getProgramBySlug(slug) {
  return PROGRAMS.find(p => p.slug === slug) ?? null
}

export function getRelatedPrograms(program, limit = 3) {
  return PROGRAMS
    .filter(p => p.field === program.field && p.id !== program.id)
    .slice(0, limit)
}

export const ALL_FIELDS = [...new Set(PROGRAMS.map(p => p.field))].sort()
